contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(string calldata description) public {
        require(!c.isAdmin(address(this)), "already admin");
        bool reverted;
        try c.newEmergencyOracle(description) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted && !c.isAdmin(address(this)));
    }
    receive() external payable {}
}
